"""This file contains Classes with the functionality for the Status Indicator and Machine State page objects"""

import builtins
import logging
import squishtest3 as sq

from interops.libraries.desktop.base_ui_page_object import BaseUIPageObject
import interops.libraries.desktop.decorators as deco
import interops.libraries.integrity.integrity_objects as integrity_objects
from interops.libraries.squish_actions import CommonActions

logger = logging.getLogger(__name__)


def wait_until_enabled(symbolic_name, timeout=100):
    '''
    Wait for the UI element to show as enabled.

    This function will continue to check the UI enabled state until it reaches
    the timeout threshold.

    Args:
        symbolic_name(str): The Squish logical name for the UI element to watch.
        timout(int): The time limit for the function in seconds.

    Returns:
        str/bool: Symbolic name if enabled within the timeout threshold, else False.
    '''
    try:
        p = sq.object.properties(sq.waitForObjectExists(symbolic_name))
        while p["enabled"] == False and timeout > 0:
            timeout -= 1
            sq.snooze(1)
            p = sq.object.properties(sq.waitForObjectExists(symbolic_name))
        return symbolic_name
    except Exception:
        return False


# ToT=Yes
def get_object_text(symbolic_name):
    '''
    Find the text for a UI element.

    Args:
        symbolic_name(str): The squish logical name for the UI element.

    Returns:
        str - Text value for the UI element, if found, else text string "object text not found".

    '''
    try:
        p = sq.object.properties(sq.waitForObjectExists(symbolic_name))
        return p["text"]
    except Exception:
        return "object text not found"


def set_edit_box(symbolic_name, setting, is_password=False, is_multi_element_edit=False):
    try:
        if not is_multi_element_edit:
            sq.mouseClick(sq.waitForObject(symbolic_name))  # , 10, 10, sq.MouseButton.PrimaryButton)
            sq.snooze(0.3)
            sq.nativeType("<Home>")
            sq.snooze(0.3)
            sq.nativeType("<Shift+End>")
            sq.snooze(0.3)
            sq.nativeType("<Delete>")
            sq.snooze(0.3)

            sq.type(sq.waitForObject(symbolic_name), setting)
            sq.snooze(0.7)
        # try alternative method if text not set
        if str(get_object_text(symbolic_name)) != str(setting) and not is_password:
            sq.mouseClick(sq.waitForObject(symbolic_name))
            sq.nativeType(setting)
            sq.nativeType("<Enter>")
        # try alternative method if text not set
        if str(get_object_text(symbolic_name)) != str(setting) and not is_password:
            sq.doubleClick(sq.waitForObject(symbolic_name), 10, 10, sq.MouseButton.PrimaryButton)
            sq.type(sq.waitForObject(symbolic_name), setting)

        return str(get_object_text(symbolic_name)) == str(setting)

    except Exception as e:
        logger.exception("set_edit_box()" + str(e))
        return False


class StatusIndicator(BaseUIPageObject):
    application_name = "RTDShell"

    MACHINE_STATE_PREPARATORY = "Preparatory"
    MACHINE_STATE_READY = "Ready to Start"
    MACHINE_STATE_RADIATION_ON = "Radiation On"
    MACHINE_STATE_CLOSED = "Closed"
    MACHINE_STATE_TERMINATED_OK = "Terminated OK"
    MACHINE_STATE_TERMINATED = ["Terminated Fault", "Terminated OK"]
    MACHINE_STATE_INTERRUPTED_READY = "Interrupted Ready"
    MACHINE_STATE_INTERRUPTED = "Interrupted"
    MACHINE_STATE_TERMINATED_FAULT = "Terminated Fault"

    MACHINE_INHIBIT_FACILITY_1_STATE = "Facility 1 State"

    @deco.app_ctx_function()
    def ready(self):
        try:
            sq.waitForObjectExists(integrity_objects.machine_State)
            sq.waitForObjectExists(integrity_objects.inhibits)
            return True
        except Exception:
            return False

    @deco.app_ctx_function()
    def get_machine_state(self):
        try:
            return CommonActions.get_objects_text_value(integrity_objects.machine_State).strip()
        except Exception:
            return "error reading machine state"

    @deco.app_ctx_function()
    def get_inhibits(self):
        try:
            return get_object_text(integrity_objects.inhibits).strip()
        except Exception:
            return "error reading inhibits"

    @deco.app_ctx_function()
    def openInhibitsPopup(self):

        try:
            sq.doubleClick(sq.waitForObject(integrity_objects.inhibits))
            return True
        except Exception as e:
            logger.info("Open inhibits popup issue " + str(e))
            return False

    def closeInhibitsPopup(self):
        try:
            sq.clickButton(sq.waitForObject(integrity_objects.oK_Button))
            return True
        except Exception as e:
            logger.info("Close inhibits popup issue " + str(e))
            return False

    def get_interlock_state(self):
        return get_object_text(integrity_objects.interlock_state).strip()

    # @deco.app_ctx_function()
    def wait_for_machine_state(self, state, timeout=30):
        ''' args state(str) or [(str),(str)..]:'''
        if builtins.type(state)==str:
            state=[state]

        try:
            machine_state = self.get_machine_state()
            while machine_state not in state:
                sq.snooze(1)
                machine_state = self.get_machine_state()
                timeout -= 1
                if timeout < 1:
                    logging.error("machine not required state, required state - " +
                                  str(state) + ", Actual state - " + machine_state)
                    return False

            return True
        except Exception as e:
            logging.exception("wait_for_machine_state threw an exception - " + str(e))
            return False


class select_machine_state(BaseUIPageObject):

    # ToT=Yes
    def press_mlc_reset(self):
        try:
            sq.mousePress(sq.waitForObject(integrity_objects.linac_MLC_Reset_Button))
            sq.snooze(1)
            sq.mouseRelease(sq.waitForObject(integrity_objects.linac_MLC_Reset_Button))
        except Exception:
            return False

    def close_page(self):
        try:
            sq.mouseClick(sq.waitForObject(integrity_objects.sms_close))
        except Exception:
            return False
